// Historical Evidence Lookup - Kern-Logik (Audit-Konzept 2026-08-24, Kap. 9).
// Matching-Hierarchie deterministisch, kein Embedding/KI-Aehnlichkeit:
//   1. Ticker + news_category   2. Ticker (beliebige Kategorie)
//   3. Sektor + news_category   4. Sektor (beliebige Kategorie)
//   5. Gesamter Datenbestand (Fallback, deutlich gekennzeichnet)
// Erste Stufe mit mindestens 1 nicht-konfundiertem Fall wird verwendet (nicht die
// erste Stufe, die die volle Mindeststichprobe erreicht - siehe Testplan Kap. 19,
// "Nur 1 Vergleichsfall": wird gezeigt, nicht durch eine breitere, weniger passende
// Stufe verdraengt). evidence_sufficient markiert ehrlich, ob die Stichprobe die
// Mindestgroesse erreicht (10 auf Ticker-Ebene, 20 auf Sektor-/Gesamtbestand-Ebene) -
// unterhalb dessen liefert message woertlich "Historische Evidenz nicht ausreichend",
// nie eine erfundene Quote (Abnahmekriterium Kap. 20).
function safeBool(v) { return v === true || v === 'true'; }
function num(v) { const n = Number(v); return (v === null || v === undefined || v === '' || isNaN(n)) ? null : n; }
const HORIZONS = ['d1', 'd3', 'd5', 'd10', 'd20'];

function median(arr) {
  if (!arr.length) return null;
  const s = [...arr].sort((a, b) => a - b);
  const mid = Math.floor(s.length / 2);
  return s.length % 2 ? s[mid] : (s[mid - 1] + s[mid]) / 2;
}
function avg(arr) { return arr.length ? arr.reduce((a, b) => a + b, 0) / arr.length : null; }

function computeTierStats(tierRows, tierNumber, threshold) {
  const usable = tierRows.filter(r => !safeBool(r.confounded));
  const confoundedRows = tierRows.filter(r => safeBool(r.confounded));
  const horizonStats = {};
  for (const h of HORIZONS) {
    const returns = usable.map(r => num(r['return_' + h])).filter(v => v !== null);
    const abnormal = usable.map(r => num(r['abnormal_return_' + h])).filter(v => v !== null);
    const hits = usable.map(r => r['direction_correct_' + h]).filter(v => v === true || v === false);
    horizonStats[h] = {
      n: returns.length,
      median_return: median(returns),
      avg_return: avg(returns),
      avg_abnormal_return: avg(abnormal),
      direction_hit_rate: hits.length ? hits.filter(Boolean).length / hits.length : null,
      direction_hit_n: hits.length
    };
  }
  const sampleSize = usable.length;
  const evidenceSufficient = sampleSize >= threshold;
  const notBelastbar = sampleSize === 1;
  let message = null;
  if (sampleSize === 0) message = 'Historische Evidenz nicht ausreichend';
  else if (!evidenceSufficient) message = 'Historische Evidenz nicht ausreichend (n=' + sampleSize + ', unterhalb Mindeststichprobe ' + threshold + ')';
  else if (notBelastbar) message = 'n=1, nicht belastbar';
  return {
    match_tier: tierNumber,
    sample_size: sampleSize,
    confounded_count: confoundedRows.length,
    distinct_ticker_count: new Set(usable.map(r => r.ticker)).size,
    evidence_sufficient: evidenceSufficient,
    not_belastbar_single_case: notBelastbar,
    message,
    horizon_stats: horizonStats,
    matched_case_ids: usable.map(r => r.id),
    confounded_case_ids: confoundedRows.map(r => r.id)
  };
}

const trig = $('Execute Workflow Trigger').first().json;
const ticker = String(trig.ticker || '').trim();
const sektor = String(trig.sektor || '').trim();
const newsCategory = String(trig.news_category || '').trim();
const newsId = trig.news_id !== undefined && trig.news_id !== '' ? trig.news_id : null;
const asOfDate = trig.as_of_date || null;

const rows = $input.all().map(i => i.json);

const tierDefs = [
  { n: 1, threshold: 10, filter: r => r.ticker === ticker && r.news_category === newsCategory },
  { n: 2, threshold: 10, filter: r => r.ticker === ticker },
  { n: 3, threshold: 20, filter: r => r.sektor === sektor && r.news_category === newsCategory },
  { n: 4, threshold: 20, filter: r => r.sektor === sektor },
  { n: 5, threshold: 20, filter: () => true }
];

let result = null;
for (const t of tierDefs) {
  const tierRows = rows.filter(t.filter);
  const usableCount = tierRows.filter(r => !safeBool(r.confounded)).length;
  if (usableCount >= 1) {
    result = computeTierStats(tierRows, t.n, t.threshold);
    break;
  }
}
if (!result) {
  // Selbst Tier 5 (Gesamtbestand) hat keinen einzigen nicht-konfundierten Fall.
  result = computeTierStats(rows, 5, 20);
}

return [{
  json: {
    ticker, sektor, news_category: newsCategory, news_id: newsId, as_of_date: asOfDate,
    ...result
  }
}];

// Gibt das Statistik-Objekt aus "Werte Matching-Hierarchie aus" als Rueckgabewert des
// Subworkflows zurueck - der Insert-Node davor liefert nur {id: ...} des Log-Eintrags,
// nicht die eigentliche Antwort fuer den Aufrufer (analog "Stelle Kontext ... wieder
// her"-Muster in P9/P10/P11).
const original = $('Werte Matching-Hierarchie aus').first().json;
const logId = $json.id ?? null;
return [{ json: { ...original, lookup_log_id: logId } }];
